package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

class LoanMapper {

    Loan toDomain(LoanJpaEntity entity) {
        CreditCheckEmbeddable creditCheck = entity.getCreditCheck();
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(), entity.getLoanedAt(),
                entity.getDueAt(), entity.getReturnedAt(),
                new CreditCheck(creditCheck.isApproved(), creditCheck.getScore(), creditCheck.getReasonCodes(),
                        creditCheck.getCheckedAt(), creditCheck.getProviderName(), creditCheck.getProviderVersion()));
    }

    LoanJpaEntity toEntity(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(), loan.getDueAt(),
                loan.getReturnedAt(),
                new CreditCheckEmbeddable(creditCheck.approved(), creditCheck.score(), creditCheck.checkedAt(),
                        creditCheck.providerName(), creditCheck.providerVersion(), creditCheck.reasonCodes()));
    }
}

