package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.in.LoanBookUseCase.LoanBookCommand;
import com.example.lending.application.port.in.ReturnLoanUseCase;
import com.example.lending.application.port.in.ReturnLoanUseCase.ReturnLoanCommand;
import com.example.lending.domain.Loan;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDate;
import java.util.UUID;

@RestController
@RequestMapping("/loans")
public class LoanController {

    private final LoanBookUseCase loanBookUseCase;
    private final ReturnLoanUseCase returnLoanUseCase;

    public LoanController(LoanBookUseCase loanBookUseCase, ReturnLoanUseCase returnLoanUseCase) {
        this.loanBookUseCase = loanBookUseCase;
        this.returnLoanUseCase = returnLoanUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public LoanResponse loanBook(@RequestBody LoanRequest request) {
        Loan loan = loanBookUseCase.loanBook(
                new LoanBookCommand(request.bookId(), request.memberId(), request.loanedAt()));
        return LoanResponse.from(loan);
    }

    @PostMapping("/{loanId}/return")
    public ReturnLoanResponse returnLoan(@PathVariable UUID loanId,
                                         @RequestBody(required = false) ReturnLoanRequest request) {
        LocalDate returnedAt = request == null ? null : request.returnedAt();
        Loan loan = returnLoanUseCase.returnLoan(new ReturnLoanCommand(loanId, returnedAt));
        return ReturnLoanResponse.from(loan);
    }
}

package com.example.lending.adapter.in.web;

import com.example.lending.domain.AlreadyReservedException;
import com.example.lending.domain.BookAlreadyOnLoanException;
import com.example.lending.domain.BookAvailableException;
import com.example.lending.domain.BookDiscardedException;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.CannotDiscardBookOnLoanException;
import com.example.lending.domain.LoanAlreadyReturnedException;
import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.LoanNotFoundException;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.ReservedForOtherException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(BookDiscardedException.class)
    public ResponseEntity<ApiErrorResponse> handleBookDiscarded(BookDiscardedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ApiErrorResponse("BOOK_DISCARDED"));
    }

    @ExceptionHandler(CannotDiscardBookOnLoanException.class)
    public ResponseEntity<ApiErrorResponse> handleDiscardOnLoan(CannotDiscardBookOnLoanException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ApiErrorResponse("BOOK_ON_LOAN"));
    }

    @ExceptionHandler(BookAvailableException.class)
    public ResponseEntity<ApiErrorResponse> handleBookAvailable(BookAvailableException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ApiErrorResponse("BOOK_AVAILABLE"));
    }

    @ExceptionHandler(AlreadyReservedException.class)
    public ResponseEntity<ApiErrorResponse> handleAlreadyReserved(AlreadyReservedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ApiErrorResponse("ALREADY_RESERVED"));
    }

    @ExceptionHandler(ReservedForOtherException.class)
    public ResponseEntity<ApiErrorResponse> handleReservedForOther(ReservedForOtherException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ApiErrorResponse("RESERVED_FOR_OTHER"));
    }

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<ApiErrorResponse> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ApiErrorResponse("LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    public ResponseEntity<ApiErrorResponse> handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ApiErrorResponse("ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}

