package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class CreditCheckIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void blocked_member_is_rejected_with_credit_rejected_error() throws Exception {
        String memberId = registerMember("BLOCKED-kim");
        String bookId = registerBook("Rejected Loan Book");

        mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId, "2026-03-02")))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("CREDIT_REJECTED"));
    }

    @Test
    void book_stays_loanable_after_credit_rejection() throws Exception {
        String blockedMemberId = registerMember("BLOCKED-lee");
        String otherMemberId = registerMember("정우성");
        String bookId = registerBook("Still Available");

        mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, blockedMemberId, "2026-03-02")))
                .andExpect(status().isConflict());

        mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, otherMemberId, "2026-03-03")))
                .andExpect(status().isCreated());
    }

    @Test
    void rejected_loan_leaves_no_loan_record() throws Exception {
        String memberId = registerMember("BLOCKED-park");
        String bookId = registerBook("No Record Book");

        mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId, "2026-03-02")))
                .andExpect(status().isConflict());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void approved_loan_returns_credit_check_result_with_loan_detail() throws Exception {
        String memberId = registerMember("김민지");
        String bookId = registerBook("Approved Loan Book");
        String loanId = loanBook(bookId, memberId, "2026-03-02");

        mockMvc.perform(get("/loans/{loanId}", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.bookId").value(bookId))
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.loanedAt").value("2026-03-02"))
                .andExpect(jsonPath("$.dueAt").value("2026-03-16"))
                .andExpect(jsonPath("$.creditCheck.approved").value(true))
                .andExpect(jsonPath("$.creditCheck.score").value(742))
                .andExpect(jsonPath("$.creditCheck.checkedAt").isNotEmpty());
    }

    @Test
    void unknown_loan_returns_404() throws Exception {
        mockMvc.perform(get("/loans/{loanId}", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String registerMember(String name) throws Exception {
        return readId(mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}")), "memberId");
    }

    private String registerBook(String title) throws Exception {
        return readId(mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}")), "id");
    }

    private String loanBook(String bookId, String memberId, String loanedAt) throws Exception {
        return readId(mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId, loanedAt))), "loanId");
    }

    private String loanRequest(String bookId, String memberId, String loanedAt) {
        return "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}";
    }

    private String readId(ResultActions result, String field) throws Exception {
        String body = result.andReturn().getResponse().getContentAsString();
        JsonNode node = objectMapper.readTree(body);
        return node.get(field).asText();
    }
}

