    @ResponseStatus(HttpStatus.CREATED)
    public LoanResponse loanBook(@RequestBody LoanRequest request) {
        Loan loan = loanBookUseCase.loanBook(
                new LoanBookCommand(request.bookId(), request.memberId(), request.loanedAt()));
        return LoanResponse.from(loan);
    }

    @PostMapping("/{loanId}/return")
    public ReturnLoanResponse returnLoan(@PathVariable UUID loanId,
                                         @RequestBody(required = false) ReturnLoanRequest request) {
        LocalDate returnedAt = request == null ? null : request.returnedAt();
        Loan loan = returnLoanUseCase.returnLoan(new ReturnLoanCommand(loanId, returnedAt));
        return ReturnLoanResponse.from(loan);
    }
